'use strict';
const products=[
{id:'food',name:'Ração Premium Cães Adultos',weight:'3 kg · Nutrição completa',price:89.90,old:109.90,category:'Cães',image:'food',reviews:42},
{id:'catfood',name:'Ração para Gatos Sabor Atum',weight:'1,2 kg · Mais sabor e saúde',price:39.90,category:'Gatos',image:'catfood',reviews:38},
{id:'care',name:'Cuidado e Proteção para Cães',weight:'20–40 kg · Bem-estar',price:74.90,old:89.90,category:'Saúde',image:'care',reviews:26},
{id:'petbed',name:'Caminha Aconchego Bege',weight:'Tamanho M · Descanso perfeito',price:129.90,category:'Conforto',image:'petbed',reviews:31},
{id:'shampoo',name:'Shampoo Cuidado Suave',weight:'473 ml · Pelagem macia',price:49.90,category:'Higiene',image:'shampoo',reviews:19},
{id:'toys',name:'Kit Brinquedos Diversão',weight:'2 peças · Para brincar juntos',price:29.90,old:39.90,category:'Brinquedos',image:'toys',reviews:24}];
let cart={};let favorites=new Set();let filter={query:'',category:'',offers:false,favorites:false};let expanded=false;let toastTimer;
const $=s=>document.querySelector(s);const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
function notify(text){$('.toast').textContent=text;$('.toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('.toast').classList.remove('visible'),3400)}
function openDialog(id){const dialog=$(id);if(!dialog.open)dialog.showModal()}
function info(title,text){$('#info-title').textContent=title;$('#info-content').replaceChildren();for(const paragraph of text.split('\n')){const p=document.createElement('p');p.textContent=paragraph;$('#info-content').append(p)}openDialog('#info-dialog')}
function renderProducts(){let list=products.filter(p=>(!filter.category||p.category===filter.category)&&(!filter.query||`${p.name} ${p.category} ${p.weight}`.toLocaleLowerCase('pt-BR').includes(filter.query))&&(!filter.offers||p.old)&&(!filter.favorites||favorites.has(p.id)));if(!expanded&&!filter.category&&!filter.query&&!filter.offers&&!filter.favorites)list=list.slice(0,5);$('#product-grid').innerHTML=list.map(p=>`<article class="product">${p.old?'<span class="sale-label">OFERTA</span>':''}<button class="favorite icon-button ${favorites.has(p.id)?'selected':''}" data-favorite="${p.id}" aria-label="${favorites.has(p.id)?'Remover dos':'Adicionar aos'} favoritos: ${p.name}" aria-pressed="${favorites.has(p.id)}"><svg class="icon"><use href="#heart"/></svg></button><div class="product-image"><img src="assets/${p.image}-480.webp" srcset="assets/${p.image}-480.webp 480w, assets/${p.image}-960.webp 960w, assets/${p.image}-1920.webp 1920w, assets/${p.image}-4k.webp 3840w" sizes="(max-width: 760px) 45vw, 240px" alt="${p.name}" loading="lazy"></div><h3>${p.name}</h3><p class="product-weight">${p.weight}</p><p class="product-price">${money(p.price)}${p.old?`<span class="old-price">${money(p.old)}</span>`:''}</p><span class="stars" aria-label="5 estrelas">★★★★★ <small>(${p.reviews})</small></span><button class="button" data-add="${p.id}">Adicionar ao carrinho</button></article>`).join('');$('#empty-products').hidden=!!list.length;const filtered=filter.category||filter.query||filter.offers||filter.favorites;$('.filter-bar').hidden=!filtered;$('#filter-label').textContent=filter.category||(filter.query?`Busca: ${$('#search').value}`:filter.offers?'Ofertas especiais':filter.favorites?'Seus favoritos':'');$('#favorite-view').setAttribute('aria-pressed',String(filter.favorites))}
function addToCart(id,qty=1){if(!products.some(p=>p.id===id)||!Number.isInteger(qty)||qty<1||qty>20)throw new Error('Produto ou quantidade inválida');cart[id]=(cart[id]||0)+qty;renderCart();notify('Mais carinho no carrinho!')}
function renderCart(){const entries=Object.entries(cart);const total=entries.reduce((sum,[id,q])=>sum+products.find(p=>p.id===id).price*q,0);$('#cart-count').textContent=entries.reduce((sum,[,q])=>sum+q,0);$('#cart-total').textContent=money(total);$('#cart-items').innerHTML=entries.length?entries.map(([id,q])=>{const p=products.find(p=>p.id===id);return `<div class="cart-item"><img src="assets/${p.image}-480.webp" srcset="assets/${p.image}-480.webp 480w, assets/${p.image}-960.webp 960w, assets/${p.image}-1920.webp 1920w, assets/${p.image}-4k.webp 3840w" sizes="(max-width: 760px) 45vw, 240px" alt="${p.name}"><div><h3>${p.name}</h3><p>${money(p.price)}</p><div class="quantity"><button data-quantity="${id}" data-change="-1" aria-label="Diminuir quantidade de ${p.name}">−</button><span>${q}</span><button data-quantity="${id}" data-change="1" aria-label="Aumentar quantidade de ${p.name}">+</button></div><button class="remove-item" data-remove="${id}">Remover</button></div><strong>${money(p.price*q)}</strong></div>`}).join(''):'<p class="empty-state">Seu carrinho está esperando um pouco de carinho.<br>Explore nossos produtos e escolha os favoritos do seu pet.</p>';$('#checkout-button').disabled=!entries.length;$('#checkout-button').style.opacity=entries.length?'1':'.5'}
function resetFilter(){filter={query:'',category:'',offers:false,favorites:false};$('#search').value='';renderProducts()}
function scrollProducts(){$('#produtos').scrollIntoView({behavior:'smooth',block:'start'})}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add)addToCart(add.dataset.add);const fav=e.target.closest('[data-favorite]');if(fav){const id=fav.dataset.favorite;favorites.has(id)?favorites.delete(id):favorites.add(id);renderProducts();notify(favorites.has(id)?'Produto salvo nos favoritos.':'Produto removido dos favoritos.')}const category=e.target.closest('[data-category]');if(category){resetFilter();filter.category=category.dataset.category;expanded=true;renderProducts();scrollProducts()}const remove=e.target.closest('[data-remove]');if(remove){delete cart[remove.dataset.remove];renderCart()}const quantity=e.target.closest('[data-quantity]');if(quantity){const id=quantity.dataset.quantity;cart[id]+=Number(quantity.dataset.change);if(cart[id]<=0)delete cart[id];renderCart()}if(e.target.closest('.cart-toggle')){renderCart();openDialog('#cart-dialog')}if(e.target.closest('[data-booking]'))openDialog('#booking-dialog');const close=e.target.closest('.close-dialog');if(close)close.closest('dialog').close();const social=e.target.closest('[data-social]');if(social)info(`Pata & Cia no ${social.dataset.social}`,'Nosso perfil será disponibilizado aqui em breve. Enquanto isso, explore os produtos e conheça nossos cuidados.');const policy=e.target.closest('[data-info]');if(policy){const texts={'Dúvidas frequentes':'Como escolher a ração? Considere a idade, o porte e as necessidades do seu pet. Para necessidades específicas, consulte o veterinário.\nComo agendar banho e tosa? Escolha o serviço, a data e o horário no formulário de agendamento.','Entregas e frete':'O prazo e o valor da entrega dependem do endereço e dos produtos escolhidos. As opções de envio serão apresentadas antes da confirmação da compra.','Trocas e devoluções':'Guarde a embalagem e os itens recebidos. Nossa equipe pode orientar sobre trocas, devoluções e eventuais problemas com o pedido.','Privacidade':'Esta página usa apenas o estado temporário da sua sessão para o carrinho e os favoritos. Os formulários desta versão não enviam dados para serviços externos.'};info(policy.dataset.info,texts[policy.dataset.info])}});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close()}});
$('.menu-toggle').addEventListener('click',()=>{const open=$('.nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',String(open))});$('.nav').addEventListener('click',()=>{$('.nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false')});
$('.search-form').addEventListener('submit',e=>{e.preventDefault();scrollProducts()});$('#search').addEventListener('input',e=>{filter.query=e.target.value.trim().toLocaleLowerCase('pt-BR');expanded=true;renderProducts()});
$('#favorite-view').addEventListener('click',()=>{const active=!filter.favorites;resetFilter();filter.favorites=active;expanded=true;renderProducts();scrollProducts()});$('#clear-filter').addEventListener('click',resetFilter);$('#view-all').addEventListener('click',()=>{resetFilter();expanded=true;renderProducts();notify('Todos os produtos estão disponíveis abaixo.')});$('#all-categories').addEventListener('click',()=>{resetFilter();expanded=true;renderProducts()});$('#offers-button').addEventListener('click',()=>{resetFilter();filter.offers=true;expanded=true;renderProducts();scrollProducts()});
$('#checkout-button').addEventListener('click',()=>{if(!Object.keys(cart).length)return;$('#cart-dialog').close();info('Seu pedido está quase pronto','Os produtos escolhidos estão no carrinho. A finalização com endereço, frete e pagamento estará disponível após a ativação da loja. Nenhum pagamento foi realizado.')});
$('#newsletter-form').addEventListener('submit',e=>{e.preventDefault();if(e.currentTarget.reportValidity())info('Vamos ficar pertinho!','O cadastro de novidades estará disponível em breve. Seu e-mail não foi enviado para nenhum serviço externo.')});
const localDate=new Date();const today=`${localDate.getFullYear()}-${String(localDate.getMonth()+1).padStart(2,'0')}-${String(localDate.getDate()).padStart(2,'0')}`;$('#booking-date').min=today;
$('#booking-form').addEventListener('submit',e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;const data=new FormData(e.currentTarget);if(data.get('date')<today){$('#booking-date').setCustomValidity('Escolha uma data a partir de hoje.');$('#booking-date').reportValidity();return}const date=new Date(data.get('date')+'T12:00:00').toLocaleDateString('pt-BR');$('#booking-message').textContent=`${data.get('name')}, você escolheu ${data.get('service').toLowerCase()} para ${data.get('pet')} em ${date}, às ${data.get('time')}. O envio do pedido ficará disponível após a ativação da agenda. Nenhuma reserva foi confirmada.`;$('#booking-message').hidden=false});$('#booking-date').addEventListener('input',()=>$('#booking-date').setCustomValidity(''));
$('#reviews-toggle').addEventListener('click',()=>{const panel=$('.more-reviews');panel.hidden=!panel.hidden;$('#reviews-toggle').textContent=panel.hidden?'Ver mais histórias ↗':'Ver menos histórias'});
renderProducts();renderCart();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'add_products_to_cart',title:'Adicionar produtos ao carrinho',description:'Adiciona produtos ao carrinho temporário da página. Não finaliza compras nem realiza pagamentos.',inputSchema:{type:'object',properties:{items:{type:'array',items:{type:'object',properties:{id:{type:'string'},quantity:{type:'integer',minimum:1,maximum:20}},required:['id','quantity'],additionalProperties:false},minItems:1}},required:['items'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Array.isArray(input.items)||!input.items.length||input.items.some(i=>!products.some(p=>p.id===i.id)||!Number.isInteger(i.quantity)||i.quantity<1||i.quantity>20))throw new Error('Produtos ou quantidades inválidos');for(const i of input.items)addToCart(i.id,i.quantity);return{items:Object.entries(cart).map(([id,quantity])=>({id,quantity}))}}})).catch(()=>{})}catch{}}
